INSERT INTO `dt_pilar` (`id_pilar`, `nama_pilar`, `deskripsi_pilar`) VALUES
('1', 'PILAR PENDIDIKAN', 'Program peningkatan mutu SDM dengan menjalankan berbagai program di bidang pendidikan berupa pemenuhan sarana dan biaya pendidikan.'),
('2', 'PILAR KESEHATAN', 'Program Lazismu yang berfokus pada pemenuhan hak-hak mustahik untuk mendapatkan kehidupan yang berkualitas melalui layanan kesehatan atau prokes.'),
('3', 'PILAR EKONOMI', 'Program peningkatan kesejahteraan penerima manfaat dana Zakat dan donasi lainnya dengan pola pemberdayaan maupun pelatihan-pelatihan wirausaha.'),
('4', 'PILAR DAKWAH', 'Pilar yang berfungsi menguatkan sisi ruhani dan pemenuhan kebutuhan untuk kegiatan dakwah dengan tujuan kemandirian para da’i dan institusi dakwah.'),
('5', 'PILAR KEMANUSIAAN', 'Penanganan masalah sosial yang timbul akibat ekses external terhadap kehidupan mustahik, seperti bantuan bencana, pendampingan manula dan kegiatan karikatif.'),
('6', 'PROGRAM RUTIN', 'Program yang dilaksanakan secara rutin setiap periode / tahun yang bermanfaat bagi umat.');
